421	
422	func transferParamsSig(req TransferRequest) string {
423		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
424		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
425		// 冲突拒绝。
426		b, _ := json.Marshal(struct {
427			Kind          string `json:"kind"`
428			ItemID        string `json:"item_id"`
429			ExpectedOwner string `json:"expected_owner"`
430			ExpectedVer   int64  `json:"expected_version"`
431			ToID          string `json:"to_id"`
432			Price         int64  `json:"price,omitempty"`
433			Reason        string `json:"reason"`
434		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
435		return string(b)
436	}
437	
438	// transferOutcome 是一笔成功转让落盘后的执行结果，供各转让入口组装
439	// 各自的返回结构与请求记录。
440	type transferOutcome struct {
441		seq     int64      // 转让历史序号
442		fromID  string     // 转让前持有人
443		fromVer int64      // 转让前持有版本
444		royalty royaltyRec // 版税应付记录（含价款、明细与余款）
445	}
446	
447	// toVer 是转让后的持有版本。
448	func (o transferOutcome) toVer() int64 { return o.fromVer + 1 }
449	
450	// applyTransfer 完成一笔成功转让的全部状态变化：持有版本加一并换主、
451	// 追加转让历史、按所属系列的版税规则快照计算应付明细与归转让前持有人
452	// 的余款。直接转让、授权代转与整批转让共用这一段逻辑，保证同一笔转让
453	// 的持有、历史与金额记录始终一致；authID 为空表示直接转让。调用方负责
454	// 前置校验、请求结果登记与落盘，调用时必须持有锁且校验已通过。
455	func (r *Registry) applyTransfer(itemID, toID, operator, reason, requestID, authID string, price int64) transferOutcome {
456		h := r.state.Holdings[itemID]
457		seq := r.state.NextSeq + 1
458		r.state.NextSeq = seq
459		from := h.OwnerID
460		fromVer := h.Version
461		h.OwnerID = toID
462		h.Version = fromVer + 1
463		r.state.Holdings[itemID] = h
464		r.state.History = append(r.state.History, historyEntry{
465			Seq: seq, Kind: "transfer", ItemID: itemID, Operator: operator,
466			Reason: reason, RequestID: requestID,
467			FromID: from, ToID: toID, FromVersion: fromVer, ToVersion: fromVer + 1,
468			AuthID: authID,
469		})
470		// 版税按所属系列的规则快照计算；余款归转让前持有人。
471		it := r.state.Items[itemID]
472		royalty := newRoyaltyRec(seq, itemID, it.SeriesID, price,
473			r.state.Series[it.SeriesID].Royalty, from)
474		r.state.Royalties[seq] = royalty
475		return transferOutcome{seq: seq, fromID: from, fromVer: fromVer, royalty: royalty}
476	}
477	
478	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
479	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
480	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
481	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
482	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
483	// 请求重复提交（即使藏品后来已易手）返回首次结果。
484	//
485	// 状态类拒绝的落盘失败时，与整批转让一致：返回保存错误（保留实际写入
486	// 错误）而非该业务错误，结果为空（无藏品编号、无持有变化、无历史序号、
487	// 无金额、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；
488	// 保存条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝
489	// 条件仍在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则
490	// 正常转出。
491	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
492		if err := req.validatePresent(); err != nil {
493			return TransferResult{}, err
494		}
495		r.mu.Lock()
496		defer r.mu.Unlock()
497		if err := r.checkOpen(); err != nil {
498			return TransferResult{}, err
499		}
500	
501		key := requestKey(req.Operator, req.RequestID)
502		sig := transferParamsSig(req)
503		if prev, ok := r.state.Requests[key]; ok {
504			return r.replayTransfer(prev, sig)
505		}
506	
507		bizErr := r.checkTransfer(req)
508		if bizErr != nil {
509			if !isValidationErr(bizErr) {
510				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
511				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
512				r.state.Requests[key] = request{
513					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
514					Params: sig, Rejected: true, Reason: errCode(bizErr),
515					ItemID: req.ItemID,
516				}
517				if err := r.commit(); err != nil {
518					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批转让一致——
519					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
520					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
521					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
522					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
523					// 的情形。整体返回空结果：无藏品编号、无持有变化、无历史
524					// 序号、无金额、不标回放、结果中业务错误为空，error 保留
525					// 实际写入错误。
526					delete(r.state.Requests, key)
527					return TransferResult{}, err
528				}
529			}
530			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
531			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
532		}
533	
534		// 持有变化、历史、版税应付与请求结果在同一临界区内一次落盘。
535		out := r.applyTransfer(req.ItemID, req.ToID, req.Operator, req.Reason, req.RequestID, "", req.Price)
536		r.state.Requests[key] = request{
537			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
538			Params: sig, ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
539			Version: out.toVer(), TxSeq: out.seq,
540		}
541		if err := r.commit(); err != nil {
542			return TransferResult{}, err
543		}
544		return TransferResult{ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
545			Version: out.toVer(), TxSeq: out.seq,
546			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
547			Remainder: out.royalty.Remainder}, nil
548	}
549	
550	// checkTransfer 按单件转让的优先级执行与整批共用的直接转让资格规则：
551	// 参数合法后，藏品及持有记录不存在优先于账户错误，操作者的登记和停用
552	// 问题优先于接收账户问题，接收账户问题优先于收发同人，收发同人又优先
553	// 于持有信息不符。
554	func (r *Registry) checkTransfer(req TransferRequest) error {
555		return r.checkSingleTransferEligibility(directTransferEligibility{
556			itemID:        req.ItemID,
557			operator:      req.Operator,
558			toID:          req.ToID,
559			expectedOwner: req.ExpectedOwner,
560			expectedVer:   req.ExpectedVer,
561		})
562	}
563	
564	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
565		if prev.Kind != "transfer" || prev.Params != sig {
566			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
567				ErrRequestConflict, prev.Operator, prev.RequestID)
568		}
569		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
570			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
571		if prev.Rejected {
572			res.Err = codeErr(prev.Reason)
573			return res, res.Err
574		}
575		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
576		// 价款与应付明细，不重复计入。
577		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
578		return res, nil
579	}
580	
581	// ---- 限时一次性代转授权 ----
582	
583	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
584	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
585	func authzCurrentStatus(a authzRec, now time.Time) string {
586		switch a.Status {
587		case "revoked":
588			return AuthRevoked
589		case "used":
590			return AuthUsed
591		}
592		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
593			return AuthExpired
594		}
595		return AuthActive
596	}
